-- Reporting, timetable safety and admit-card foundation.
create table public.admit_cards(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schools(id) on delete cascade,exam_id uuid not null references public.exams(id) on delete cascade,student_id uuid not null references public.students(id) on delete cascade,card_no text not null,issued_on date not null default current_date,issued_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(school_id,card_no),unique(exam_id,student_id));
alter table public.admit_cards enable row level security;
create policy "admit authorized read" on public.admit_cards for select to authenticated using(public.can_mark_academics(school_id) or public.can_view_student(student_id));
create policy "admit manage" on public.admit_cards for all to authenticated using(public.has_school_role(school_id,array['school_owner','principal']::public.school_role[])) with check(public.has_school_role(school_id,array['school_owner','principal']::public.school_role[]));
create index admit_exam_idx on public.admit_cards(exam_id,student_id);
create or replace function public.validate_timetable_collision() returns trigger language plpgsql security invoker set search_path=public as $$begin
 if exists(select 1 from public.timetable_entries t where t.school_id=new.school_id and t.academic_year_id=new.academic_year_id and t.weekday=new.weekday and t.id<>new.id and t.starts_at<new.ends_at and t.ends_at>new.starts_at and ((new.staff_id is not null and t.staff_id=new.staff_id) or (t.class_id=new.class_id and coalesce(t.section_id,'00000000-0000-0000-0000-000000000000'::uuid)=coalesce(new.section_id,'00000000-0000-0000-0000-000000000000'::uuid)) or (new.room is not null and new.room<>'' and t.room=new.room))) then raise exception 'Timetable collision: teacher, class/section, or room is already occupied';end if;return new;end;$$;
drop trigger if exists timetable_collision_guard on public.timetable_entries;create trigger timetable_collision_guard before insert or update on public.timetable_entries for each row execute function public.validate_timetable_collision();